    required>
</div>
                  <div class="col-md-3">
                  <label>Name</label>
                  <input type="text" v-model="line_name" class="form-control" placeholder="Enter Activity List Name" required>
                </div>
                <div class="col-md-3 mt-2">
                  <label>Quantity {{ line_budget_item_description?.quantity }}</label>
                  <input type="number" v-model="line_quantity" class="form-control" placeholder="Enter Quantity" step="any" required>
                </div>
               <div class="col-md-3 mt-2">
  <label>Unit</label>
  <input type="text" class="form-control" :value="line_budget_item_description?.units || ''" readonly>
</div>
                <div class="col-md-3 mt-2">
                  <label>Rate {{ line_budget_item_description?.cost ? formatNumber(line_budget_item_description.cost) : '' }}</label>
                  <input type="number" v-model="line_rate" class="form-control" placeholder="Enter Rate" step="any" required>
                </div>
              </div>
            </div>
            <div class="modal-footer">
              <button type="button" class="btn btn-danger" data-bs-dismiss="modal" @click="resetActivityLineForm()" id="close_activity_line">Close</button>
              <button type="submit" class="btn btn-primary me-2 mt-1" :disabled="isSending">
