    </div>

    <!-- Edit Activity Line -->
    <div class="modal fade mymodal" id="edit-activity-line-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="activityLineModalLabel" aria-hidden="true">
      <div class="modal-dialog modal-xl">
        <div class="modal-content">
          <div class="modal-header">
            <h1 class="modal-title fs-5" id="activityLineModalLabel">Edit Activity List For {{ selectedActivity?.name }}</h1>
            <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" @click="resetActivityLineForm()" id="close_edit_line"></button>
          </div>
          <form @submit.prevent="updateActivityLine()">
            <div class="modal-body">
              <div class="row mb-3">
                <div class="col-md-6">
                  <label>Budget Item Description</label>
                  <Multiselect v-model="line_budget_item_description" :options="budgetItemDescriptions" label="name" track-by="id" placeholder="Select budget item description" :searchable="true" :object="true" :close-on-select="true" required />
                </div>
                 <div class="col-md-3">
  <label>Start Date</label>
  <input type="date" v-model="start_date" class="form-control"
    :min="selectedActivity?.start_date"
    :max="selectedActivity?.end_date"
    required>
</div>
<div class="col-md-3">
  <label>End Date</label>
  <input type="date" v-model="end_date" class="form-control"
    :min="start_date || selectedActivity?.start_date"
    :max="selectedActivity?.end_date"
    required>
</div>
                <div class="col-md-3">
                  <label>Name</label>
                  <input type="text" v-model="line_name" class="form-control" placeholder="Enter Activity List Name" required>
                </div>
                <div class="col-md-3 mt-2">
                  <label>Quantity {{ line_budget_item_description?.quantity }}</label>
                  <input type="number" v-model="line_quantity" class="form-control" placeholder="Enter Quantity" step="any" required>
                </div>
                <div class="col-md-3 mt-2">
             <label>Unit</label>
             <input type="text" class="form-control" :value="line_budget_item_description?.units || ''" readonly>
               </div>
                <div class="col-md-3 mt-2">
                  <label>Rate {{ line_budget_item_description?.cost ? formatNumber(line_budget_item_description.cost) : '' }}</label>
                  <input type="number" v-model="line_rate" class="form-control" placeholder="Enter Rate" step="any" required>
                </div>
              </div>
            </div>
            <div class="modal-footer">
              <button type="button" class="btn btn-danger" data-bs-dismiss="modal" @click="resetActivityLineForm()" id="close_edit_line">Close</button>
              <button type="submit" class="btn btn-primary me-2 mt-1" :disabled="isSending">
                <span v-if="isSending" v-html="loadingSpinner()"></span>
                <span>Update</span>
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>

  </div>
</template>

<script setup>
import { onMounted, ref, inject, computed, watch } from 'vue';
import axios from 'axios';
import { useMeta } from '@/composables/use-meta';
import Multiselect from '@suadelabs/vue3-multiselect';
import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
import { useRoute } from 'vue-router';

const route = useRoute();
useMeta({ title: 'Work Plans' });

const showMessage  = inject('showMessage');
const showError    = inject('showError');
const formatNumber = inject('formatNumber');
const showConfirmation = inject('showConfirmation');
const loadingSpinner   = inject('loadingSpinner');
const doubleSpinner   = inject('doubleSpinner');
const pillShimmer      = inject('pillShimmer');
const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;

const loading_spinner    = ref(false);
const loadingPlans       = ref(false);
const loadingActivitiesFor = ref(null);   
const isSending          = ref(false);
const loading            = ref(false);
const updating           = ref(false);
const searchQuery        = ref('');

const workPlans    = ref([]);
const projects     = ref([]);
const budgets      = ref([]);
const budgetItemDescriptions = ref([]);

const selectedProject  = ref(null);
const selectedBudget   = ref(null);
const selectedBudgetId = ref(null);
const selectedPlan     = ref(null);       
const selectedActivity = ref(null);       
const isBudgetsloading = ref(false);

const openPlans      = ref(new Set());
const openActivities = ref(new Set());

const selectedNode = ref(null);

const name                     = ref('');
const description              = ref('');
const activity_name            = ref('');
const start_date               = ref('');
const end_date                 = ref('');
const line_name                = ref('');
const line_budget_item_description = ref('');
const line_quantity            = ref('');
const line_rate                = ref('');
const selectedActivityLine     = ref(null);

const axiosInstance = axios.create({ baseURL: process.env.VUE_APP_API_BASE_URL });

const togglePlanOpen = (planId) => {
  const next = new Set(openPlans.value);
  if (next.has(planId)) { next.delete(planId); }
  else {
    next.add(planId);
    const plan = workPlans.value.find(p => p.id === planId);
    if (plan && !plan.activities) getWorkPlanActivities(plan);
  }
  openPlans.value = next;
};

const toggleActivityOpen = (activityId) => {
  const next = new Set(openActivities.value);
  if (next.has(activityId)) next.delete(activityId);
  else next.add(activityId);
  openActivities.value = next;
};

const selectPlan = (plan) => {
  selectedPlan.value = plan;
  selectedNode.value = { id: plan.id, type: 'plan', data: plan };
  const next = new Set(openPlans.value);
  next.add(plan.id);
  openPlans.value = next;
  if (!plan.activities) getWorkPlanActivities(plan);
};

const selectActivity = (plan, activity) => {
  selectedPlan.value = plan;
  selectedActivity.value = activity;
  selectedNode.value = { id: activity.id, type: 'activity', data: activity, parentPlan: plan };
  const next = new Set(openActivities.value);
  next.add(activity.id);
  openActivities.value = next;
};

const selectLine = (plan, activity, line) => {
  selectedPlan.value = plan;
  selectedActivity.value = activity;
  selectedNode.value = { id: line.id, type: 'line', data: line, parentPlan: plan, parentActivity: activity };
};


const getPlanDateRange = (plan) => {
  const activities = plan?.activities;
  if (!activities || activities.length === 0) return { start: 'N/A', end: 'N/A' };
  const sorted = [...activities].sort((a, b) => new Date(a.start_date) - new Date(b.start_date));
  return {
    start: sorted[0]?.start_date || 'N/A',
    end:   sorted[sorted.length - 1]?.end_date || 'N/A',
  };
};

const getWorkPlan = async (showLoading = true) => {
  if (showLoading) { loading_spinner.value = true; loadingPlans.value = true; }
  try {
    const response = await axiosInstance.get(`work-plans?budget_id=${selectedBudget.value.id}`);
    const prev = workPlans.value;
    workPlans.value = response.data.map(wp => {
      const old = prev.find(p => p.id === wp.id);
      return old?.activities ? { ...wp, activities: old.activities } : wp;
    });

    await Promise.all(workPlans.value.map(plan => getWorkPlanActivities(plan)));

    openPlans.value = new Set(workPlans.value.map(p => p.id));

    const allActivityIds = new Set();
    workPlans.value.forEach(plan => {
      (plan.activities || []).forEach(act => allActivityIds.add(act.id));
    });
    openActivities.value = allActivityIds;

    if (selectedNode.value?.type === 'plan') {
      const fresh = workPlans.value.find(p => p.id === selectedNode.value.id);
      if (fresh) selectedNode.value = { ...selectedNode.value, data: fresh };
    }
  } catch (error) {
    showError(error.message);
  } finally {
    if (showLoading) { loading_spinner.value = false; loadingPlans.value = false; }
  }
};

const getWorkPlanActivities = async (plan) => {
  loadingActivitiesFor.value = plan.id;
  try {
    const response = await axiosInstance.get(`work-plan-activities?work_plan_id=${plan.id}`);
    plan.activities = response.data;
    if (selectedNode.value?.type === 'activity' && selectedNode.value.parentPlan?.id === plan.id) {
      const updatedAct = plan.activities.find(a => a.id === selectedNode.value.id);
      if (updatedAct) selectedNode.value = { ...selectedNode.value, data: updatedAct };
    }
    if (selectedNode.value?.type === 'plan' && selectedNode.value.id === plan.id) {
      selectedNode.value = { ...selectedNode.value, data: plan };
    }
  } catch (error) {
    showError(error.message);
  } finally {
    loadingActivitiesFor.value = null;
  }
};


const getProjects = async () => {
  loading_spinner.value = true;
  try {
    const response = await axiosInstance.get(`projects?company_id=6&status=active`);
    projects.value = response.data
      .filter(item => item.contracted === 'YES')
      .filter(item => item.status === 'active');
  } catch (error) {
    showError(error.message);
  } finally {
    loading_spinner.value = false;
  }
};

const getBudgets = async () => {
  isBudgetsloading.value = true;
  try {
    const response = await axiosInstance.get(`get-budgets?project_id=${selectedProject.value.id}`);
    budgets.value = response.data.filter(b => b.status === "closed");
  } catch (error) {
    showError(error.message);
  } finally {
    isBudgetsloading.value = false;
  }
};

const getBudgetItemDescriptions = async () => {
  try {
    const response = await axiosInstance.get(`get-budget-item-descriptions?budget_id=${selectedBudgetId.value}`);
    budgetItemDescriptions.value = response.data;
  } catch (error) { showError(error.message); }
};

const toggleProject = async (project) => {
  selectedProject.value  = project;
  selectedBudget.value   = null;
  selectedBudgetId.value = null;
  selectedPlan.value     = null;
  selectedActivity.value = null;
  selectedNode.value     = null;
  workPlans.value        = [];
  openPlans.value        = new Set();
  openActivities.value   = new Set();
  await getBudgets();
};

const fillBudget = (budget) => {
  if (selectedBudgetId.value === budget.id) {
    selectedBudget.value   = null;
    selectedBudgetId.value = null;
    selectedPlan.value     = null;
    selectedActivity.value = null;
    selectedNode.value     = null;
    workPlans.value        = [];
    openPlans.value        = new Set();
    openActivities.value   = new Set();
    return;
  }
  selectedBudget.value   = budget;
  selectedBudgetId.value = budget.id;
  selectedPlan.value     = null;
  selectedActivity.value = null;
  selectedNode.value     = null;
  workPlans.value        = [];
  openPlans.value        = new Set();
  openActivities.value   = new Set();
  getWorkPlan();
};

const openRegisterWorkPlanModal = () => { name.value = ''; description.value = ''; };
const closeWorkPlanModal = () => { name.value = ''; };

const registerWorkPlan = async () => {
  loading.value = true;
  const payload = {
    project_id:    selectedProject.value.id,
    registrar_id:  JSON.parse(localStorage.getItem("user")).id,
    name:          name.value,
    budget_id:     selectedBudget.value.id,
  };
  try {
    await axiosInstance.post('work-plans', payload);
    await getWorkPlan(false);
    document.getElementById('close_work_plan').click();
    showMessage('Work Plan registered successfully!');
    name.value = '';
  } catch (error) {
    showError(error.message);
  } finally {
    loading.value = false;
  }
};

const editPlan = (plan) => {
  name.value        = plan.name;
  description.value = plan.description || '';
  selectedPlan.value = plan;
};

const updateWorkPlan = async () => {
  updating.value = true;
  try {
    await axiosInstance.put(`work-plans/${selectedPlan.value.id}`, { name: name.value, description: description.value });
    await getWorkPlan(false);
    document.getElementById('close_edit_plan').click();
    showMessage('Work Plan updated successfully!');
  } catch (error) {
    showError(error.message);
  } finally {
    updating.value = false;
  }
};

const searchWorkPlans = () => { getWorkPlan(); };

const openAddActivityModal = () => { activity_name.value = ''; start_date.value = ''; end_date.value = ''; };
const closeActivityModal   = () => { activity_name.value = ''; start_date.value = ''; end_date.value = ''; };

const addWorkPlanActivity = async () => {
  isSending.value = true;
  const payload = {
    work_plan_id: selectedPlan.value.id,
    name:         activity_name.value,
    start_date:   start_date.value,
    end_date:     end_date.value,
  };
  try {
    await axiosInstance.post('work-plan-activities', payload);
    await getWorkPlanActivities(selectedPlan.value);
    showMessage('Activity added successfully!');
    document.getElementById('close_item').click();
    closeActivityModal();
  } catch (error) {
    showError(error.message);
  } finally {
    isSending.value = false;
  }
};

const openEditActivityModal = (activity) => {
  activity_name.value  = activity.name;
  start_date.value     = activity.start_date;
  end_date.value       = activity.end_date;
  selectedActivity.value = activity;
};

const updateWorkPlanActivity = async () => {
  updating.value = true;
  try {
    await axiosInstance.put(`work-plan-activities/${selectedActivity.value.id}`, {
      name:       activity_name.value,
      start_date: start_date.value,
      end_date:   end_date.value,
    });
    await getWorkPlanActivities(selectedPlan.value);
    if (selectedNode.value?.type === 'activity' && selectedNode.value.id === selectedActivity.value.id) {
      const updated = selectedPlan.value.activities?.find(a => a.id === selectedActivity.value.id);
      if (updated) selectedNode.value = { ...selectedNode.value, data: updated };
    }
    showMessage('Activity updated successfully!');
    document.getElementById('close_edit_activity').click();
    closeActivityModal();
  } catch (error) {
    showError(error.message);
  } finally {
    updating.value = false;
  }
};

const openAddActivityLineModal = (activity) => {
  selectedActivity.value = activity;
  getBudgetItemDescriptions();
};

const addActivityLine = async () => {
  isSending.value = true;
  const payload = {
    work_plan_activity_id:    selectedActivity.value.id,
    name:                     line_name.value,
    start_date:               start_date.value,
    end_date:                 end_date.value,
    budget_item_description_id: line_budget_item_description.value.id,
    quantity:                 line_quantity.value,
    rate:                     line_rate.value,
    unit: line_budget_item_description.value?.units || '',
  };
  try {
    await axiosInstance.post('work-plan-activity-lines', payload);
    await getWorkPlanActivities(selectedPlan.value);
    if (selectedNode.value?.type === 'activity' && selectedNode.value.id === selectedActivity.value.id) {
      const updated = selectedPlan.value.activities?.find(a => a.id === selectedActivity.value.id);
      if (updated) selectedNode.value = { ...selectedNode.value, data: updated };
    }
    showMessage('Activity line added successfully!');
    document.getElementById('close_activity_line').click();
    resetActivityLineForm();
  } catch (error) {
    console.log(error)
    showError(error.message);
  } finally {
    isSending.value = false;
  }
};

const openEditActivityLineModal = (line) => {
  selectedActivityLine.value = line;
  line_name.value            = line.name;
  start_date.value           = line.start_date;
  end_date.value             = line.end_date;
  line_quantity.value        = line.quantity;
  line_rate.value            = line.rate;
  if (line.budget_item_description) {
    line_budget_item_description.value = budgetItemDescriptions.value.find(d => d.id === line.budget_item_description.id) || line.budget_item_description;
  }
};

const updateActivityLine = async () => {
  isSending.value = true;
  const payload = {
    name:                       line_name.value,
    start_date:                 start_date.value,
    end_date:                   end_date.value,
    budget_item_description_id: line_budget_item_description.value.id,
    quantity:                   line_quantity.value,
    rate:                       line_rate.value,
    unit: line_budget_item_description.value?.units || '',
  };
  try {
    await axiosInstance.put(`work-plan-activity-lines/${selectedActivityLine.value.id}`, payload);
    await getWorkPlanActivities(selectedPlan.value);
    if (selectedNode.value?.type === 'line' && selectedNode.value.id === selectedActivityLine.value.id) {
      const updatedAct = selectedPlan.value.activities?.find(a => a.id === selectedActivity.value.id);
      const updatedLine = updatedAct?.lines?.find(l => l.id === selectedActivityLine.value.id);
      if (updatedLine) selectedNode.value = { ...selectedNode.value, data: updatedLine };
    }
    if (selectedNode.value?.type === 'activity' && selectedNode.value.id === selectedActivity.value.id) {
      const updatedAct = selectedPlan.value.activities?.find(a => a.id === selectedActivity.value.id);
      if (updatedAct) selectedNode.value = { ...selectedNode.value, data: updatedAct };
    }
    showMessage('Activity line updated successfully!');
    document.getElementById('close_edit_line').click();
    resetActivityLineForm();
  } catch (error) {
    showError(error.message);
  } finally {
    isSending.value = false;
  }
};

const resetActivityLineForm = () => {
  line_name.value                    = '';
  line_budget_item_description.value = '';
  line_quantity.value                = '';
  line_rate.value                    = '';
  start_date.value                   = '';
  end_date.value                     = '';
};

watch(line_quantity, (newValue) => {
  if (!line_budget_item_description.value) return;
  const maxQty = Number(line_budget_item_description.value.quantity || 0);
  if (Number(newValue) > maxQty) {
    showError(`Maximum budgeted quantity is ${maxQty}`);
    line_quantity.value = maxQty;
  }
});

watch(line_rate, (newValue) => {
  if (!line_budget_item_description.value) return;
  const maxRate = Number(line_budget_item_description.value.cost);
  if (Number(newValue) > maxRate) {
    showError(`Maximum budgeted rate is ${formatNumber(maxRate)}`);
    line_rate.value = maxRate;
  }
});

watch(line_budget_item_description, (newValue) => {
  line_quantity.value = '';
  line_rate.value     = '';
  if (newValue && Number(newValue.remaining_balance) <= 0) {
    showError(`No remaining budget balance for this item.`);
    line_budget_item_description.value = '';
  }
});

onMounted(() => {
  getProjects();
  const offcanvasElement = document.getElementById('offcanvasWithBothOptions');
  if (offcanvasElement) {
    const offcanvas = new bootstrap.Offcanvas(offcanvasElement);
    offcanvas.show();
  }
});



const formatDate = (dateStr) => {
  if (!dateStr) return '';
  const [year, month, day] = dateStr.split('-').map(Number);
  const d = new Date(year, month - 1, day);
  const dayName = d.toLocaleDateString('en-US', { weekday: 'short' });
  return `${dayName} ${month}/${day}/${String(year).slice(-2)}`;
};


const printWorkPlans = async () => {
  if (!workPlans.value || workPlans.value.length === 0) {
    showError('No work plans available to print');
    return;
  }

  try {
    for (const plan of workPlans.value) {
      if (!plan.activities) {
        await getWorkPlanActivities(plan);
      }
    }

    const calcDuration = (start, end) => {
      if (!start || !end) return '-';
      const s = new Date(start);
      const e = new Date(end);
      const diff = Math.round((e - s) / (1000 * 60 * 60 * 24)) + 1;
      return diff > 0 ? `${diff} days` : '1 day';
    };

    const fmtDate = (dateStr) => {
      if (!dateStr) return 'N/A';
      const [year, month, day] = dateStr.split('-').map(Number);
      const d = new Date(year, month - 1, day);
      const dayName = d.toLocaleDateString('en-US', { weekday: 'short' });
      return `${dayName} ${month}/${day}/${String(year).slice(-2)}`;
    };

    let budgetMinStart = null, budgetMaxEnd = null;
    workPlans.value.forEach(plan => {
      (plan.activities || []).forEach(act => {
        if (act.start_date && (!budgetMinStart || act.start_date < budgetMinStart)) budgetMinStart = act.start_date;
        if (act.end_date   && (!budgetMaxEnd   || act.end_date   > budgetMaxEnd))   budgetMaxEnd   = act.end_date;
      });
    });
    const budgetDuration = calcDuration(budgetMinStart, budgetMaxEnd);
    const budgetStart    = budgetMinStart ? fmtDate(budgetMinStart) : 'N/A';
    const budgetFinish   = budgetMaxEnd   ? fmtDate(budgetMaxEnd)   : 'N/A';

    let tableRowsHTML = '';
    let planNum = 0;

    workPlans.value.forEach(plan => {
      planNum++;
      const planDateRange = getPlanDateRange(plan);

      tableRowsHTML += `
        <tr class="row-plan">
          <td class="col-num">${planNum}</td>
          <td class="col-name" style="padding-left:10px;font-weight:700;">
            ${escapeHtml(plan.name)}
          </td>
          <td class="col-duration">${calcDuration(
            planDateRange.start !== 'N/A' ? planDateRange.start : null,
            planDateRange.end   !== 'N/A' ? planDateRange.end   : null
          )}</td>
          <td class="col-start">${planDateRange.start !== 'N/A' ? fmtDate(planDateRange.start) : 'N/A'}</td>
          <td class="col-finish">${planDateRange.end   !== 'N/A' ? fmtDate(planDateRange.end)   : 'N/A'}</td>
          <td class="col-quantity"></td>
        </tr>`;

      let actNum = 0;
      (plan.activities || []).forEach(activity => {
        actNum++;
        const actLabel = `${planNum}.${actNum}`;

        // Activity row  →  1.1, 1.2 …
        tableRowsHTML += `
          <tr class="row-activity">
            <td class="col-num">${actLabel}</td>
            <td class="col-name" style="padding-left:20px;font-weight:600;">
              ${escapeHtml(activity.name)}
            </td>
            <td class="col-duration">${calcDuration(activity.start_date, activity.end_date)}</td>
            <td class="col-start">${fmtDate(activity.start_date)}</td>
            <td class="col-finish">${fmtDate(activity.end_date)}</td>
            <td class="col-quantity"></td>
          </tr>`;

        let lineNum = 0;
        (activity.lines || []).forEach(line => {
          lineNum++;
         const lineLabel = String.fromCharCode(96 + lineNum);

          // Line row  →  1.1.1, 1.1.2 …
          tableRowsHTML += `
            <tr class="row-line">
              <td class="col-num">${lineLabel}</td>
              <td class="col-name" style="padding-left:40px;">
                ${escapeHtml(line.name)}
              </td>
              <td class="col-duration">${calcDuration(line.start_date, line.end_date)}</td>
              <td class="col-start">${fmtDate(line.start_date)}</td>
              <td class="col-finish">${fmtDate(line.end_date)}</td>
              <td class="col-quantity">${Number(line.quantity)} ${escapeHtml(line.unit || '')}</td>
            </tr>`;
        });
      });
    });

    const printContent = `
